//! The release optimizer's table (contracts/opt-passes.md "Constants"): the inlining limits, the
//! weight of every instruction and terminator, which ops a dead-code pass may delete and which
//! constant folding evaluates, and the compiler-known items that are inlined like ordinary fns.
//! The data is generated by `tools/gen-tables` from `crates/stave-ir/tables/opt.toml`, the one
//! source both compilers read.

use crate::ir::{Op, Term};
use crate::known::Known;

/// When a dead-code pass may delete an instruction whose result nothing reads.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Removable {
    No,
    Yes,
    /// Only when the result type is a float type (the int forms trap).
    Float,
    /// Only when operand 1 (the index) is a constant (a dynamic index traps).
    ConstIndex,
    /// A vector or mask op: only when it neither traps nor accesses memory.
    Lanes,
}

/// What constant folding does with an op.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Fold {
    No,
    /// Evaluated when every operand is an int constant; a trapping op only when it does not trap.
    Int,
    /// Replaced by the chosen operand when the condition (operand 0) is a constant.
    Cond,
}

/// One row of the op table. A name ending in `*` stands for every op name with that prefix that
/// no other row names.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct OpRow {
    pub name: &'static str,
    pub weight: u32,
    pub removable: Removable,
    pub fold: Fold,
}

include!("generated/opt_table.rs");

/// The row of the op spelled `name` in the IR text (`intrinsic.<name>` for an intrinsic).
pub fn row(name: &str) -> Option<&'static OpRow> {
    OPS.iter()
        .find(|r| r.name == name)
        .or_else(|| OPS.iter().find(|r| r.name.strip_suffix('*').is_some_and(|p| name.starts_with(p))))
}

/// The row of `op`.
pub fn op_row(op: Op) -> Option<&'static OpRow> {
    match op.name() {
        Some(n) => row(n),
        None => row("intrinsic.*"),
    }
}

/// The weight of a terminator.
pub fn term_weight(t: &Term) -> u32 {
    match t {
        Term::Br(_) => TERM_BR,
        Term::Cbr { .. } => TERM_CBR,
        Term::Switch { .. } => TERM_SWITCH,
        Term::Ret(_) => TERM_RET,
        Term::Unreachable => TERM_UNREACHABLE,
    }
}

/// Whether the known item `k` is inlined like an ordinary fn.
pub fn known_inline(k: Known) -> bool {
    KNOWN_INLINE.contains(&k)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::ir::{CastKind, IntrinsicId, PanicKind, Prefetch};
    use crate::simd::VecOp;

    /// Every op, one per name; the match makes a new `Op` variant a compile error here.
    fn every_op() -> Vec<Op> {
        let covered = |op: Op| match op {
            Op::Add
            | Op::Sub
            | Op::Mul
            | Op::Div
            | Op::Rem
            | Op::Neg
            | Op::AddWrap
            | Op::SubWrap
            | Op::MulWrap
            | Op::ShlWrap
            | Op::AddSat
            | Op::SubSat
            | Op::MulSat
            | Op::Shl
            | Op::Shr
            | Op::And
            | Op::Or
            | Op::Xor
            | Op::Not
            | Op::Popcount
            | Op::Clz
            | Op::Ctz
            | Op::MulWide
            | Op::Eq
            | Op::Ne
            | Op::Lt
            | Op::Le
            | Op::Gt
            | Op::Ge
            | Op::Select
            | Op::Cast(_)
            | Op::Make
            | Op::Get
            | Op::Set
            | Op::EnumMake
            | Op::EnumTag
            | Op::EnumGet
            | Op::Slot
            | Op::Load
            | Op::Store
            | Op::FieldAddr
            | Op::EnumFieldAddr
            | Op::ElemAddr
            | Op::SliceMake
            | Op::SliceLen
            | Op::SlicePtr
            | Op::FnMake
            | Op::BoundsCheck
            | Op::Prefetch(_)
            | Op::StoreStream
            | Op::FenceStream
            | Op::Call
            | Op::CallInd
            | Op::Intrinsic(_)
            | Op::Vec(_)
            | Op::Panic(_) => op,
        };
        let mut ops = vec![
            Op::Add,
            Op::Sub,
            Op::Mul,
            Op::Div,
            Op::Rem,
            Op::Neg,
            Op::AddWrap,
            Op::SubWrap,
            Op::MulWrap,
            Op::ShlWrap,
            Op::AddSat,
            Op::SubSat,
            Op::MulSat,
            Op::Shl,
            Op::Shr,
            Op::And,
            Op::Or,
            Op::Xor,
            Op::Not,
            Op::Popcount,
            Op::Clz,
            Op::Ctz,
            Op::MulWide,
            Op::Eq,
            Op::Ne,
            Op::Lt,
            Op::Le,
            Op::Gt,
            Op::Ge,
            Op::Select,
            Op::Make,
            Op::Get,
            Op::Set,
            Op::EnumMake,
            Op::EnumTag,
            Op::EnumGet,
            Op::Slot,
            Op::Load,
            Op::Store,
            Op::FieldAddr,
            Op::EnumFieldAddr,
            Op::ElemAddr,
            Op::SliceMake,
            Op::SliceLen,
            Op::SlicePtr,
            Op::FnMake,
            Op::BoundsCheck,
            Op::StoreStream,
            Op::FenceStream,
            Op::Call,
            Op::CallInd,
            Op::Intrinsic(IntrinsicId(0)),
        ];
        let casts = [CastKind::Exact, CastKind::Wrap, CastKind::Sat, CastKind::Round, CastKind::Try];
        ops.extend(casts.map(Op::Cast));
        ops.extend(Prefetch::ALL.map(Op::Prefetch));
        ops.extend(VecOp::ALL.map(Op::Vec));
        ops.extend(PanicKind::ALL.map(Op::Panic));
        ops.into_iter().map(covered).collect()
    }

    fn matching(name: &str) -> usize {
        let exact = OPS.iter().filter(|r| r.name == name).count();
        let family =
            OPS.iter().filter(|r| r.name.strip_suffix('*').is_some_and(|p| name.starts_with(p))).count();
        if exact > 0 { exact } else { family }
    }

    #[test]
    fn every_op_has_one_row() {
        for op in every_op() {
            let name = op.name().unwrap_or("intrinsic.copy_bytes");
            assert_eq!(matching(name), 1, "{name}");
            assert!(op_row(op).is_some(), "{name}");
        }
    }

    #[test]
    fn every_row_names_an_op() {
        let names: Vec<&str> =
            every_op().iter().map(|op| op.name().unwrap_or("intrinsic.copy_bytes")).collect();
        for r in &OPS {
            let hit = match r.name.strip_suffix('*') {
                Some(p) => names.iter().any(|n| n.starts_with(p)),
                None => names.contains(&r.name),
            };
            assert!(hit, "row `{}` names no op", r.name);
        }
    }

    #[test]
    fn rows_agree_with_the_ops() {
        for op in every_op() {
            let r = op_row(op).unwrap();
            // a fold never evaluates an op that is not an int, bool, or char computation
            if r.fold == Fold::Int {
                assert!(!matches!(op, Op::Vec(_) | Op::Intrinsic(_) | Op::Call | Op::Load), "{op:?}");
            }
            // an op that traps for every operand type is never deleted unread
            if r.removable == Removable::Yes {
                assert!(op.trap_kinds().is_empty(), "{op:?}");
            }
            if matches!(op, Op::Vec(_)) {
                assert_eq!(r.removable, Removable::Lanes, "{op:?}");
            }
        }
    }

    /// The `lanes` rule as the contract states it (opt-passes.md K2): a vector or mask op is
    /// removable unless it traps or touches memory, and these are the ops that do.
    #[test]
    fn lanes_rule_names_the_trapping_and_memory_ops() {
        let kept = [
            "vec.div_lanes",
            "vec.div_const",
            "vec.shl",
            "vec.shr",
            "vec.load",
            "vec.store",
            "vec.load_aligned",
            "vec.store_aligned",
            "vec.store_stream",
            "vec.load_masked",
            "vec.store_masked",
            "vec.gather",
            "vec.scatter",
        ];
        for v in VecOp::ALL {
            let removable = v.trap_kinds().is_empty() && !v.is_memory();
            assert_eq!(removable, !kept.contains(&v.name()), "{}", v.name());
        }
    }

    #[test]
    fn the_closed_size_rules_hold() {
        let call = op_row(Op::Call).unwrap().weight;
        assert!(CALL_SAVED <= call);
        assert_eq!(TERM_BR, TERM_RET);
    }

    #[test]
    fn inlined_known_items_have_no_abi() {
        for &k in &KNOWN_INLINE {
            assert!(crate::known::abi_signature(k).is_none(), "{k:?}");
            assert!(!crate::known::reports_on_alt_stack(k), "{k:?}");
        }
        assert!(known_inline(Known::SetUserSite));
        assert!(!known_inline(Known::Trap));
    }
}
